int buildRoom(int x, int y, int w, int h, int room_no) {
    int ok = 1;
    int i, j;

    // The room needs its own cells and a border of one cell around them, so
    // that two rooms never come out sharing a wall.
    for (j = -1; j < h + 2; j++) {
        for (i = -1; i < w + 2; i++) {
            if (i + x >= 0 && i + x < 20 && j + y >= 0 && j + y < 20) {
                if (buildMapDat[x + (j + y) * chronicle::dungeon::GridStride + i].kind != MAP_PARTS_NONE) {
                    ok = 0;
                }
            }
        }
    }

    if (!ok) {
        return ok;
    }

    for (j = 0; j < h; j++) {
        for (i = 0; i < w; i++) {
            buildMapDat[x + (y + j) * chronicle::dungeon::GridStride + i].kind = MAP_PARTS_ROOM_FLOOR;
            buildMapDat[x + (y + j) * chronicle::dungeon::GridStride + i].link[room_no] = 1;
            buildMapDat[x + (y + j) * chronicle::dungeon::GridStride + i].content |= BUILD_CELL_ROOM;
        }
    }

    return 1;
}

