        direction_mask = MAP_DIR_WEST;
    }

    switch (direction_mask) {
        case MAP_DIR_NORTH:
            door_part = MAP_PARTS_ROOM_GATE_NORTH;
            scanRoomInfoWork[x + (y - 1) * chronicle::dungeon::GridStride] = 0;
