int CDungeonMap::CreatPartsList(int *list, int max, int first_part, int last_part) {
    int            num = 0;
    PARTS_ADJACENT adjacent = {
        {{0, -1}, {0, 1}, {-1, 0}, {1, 0}}
    };
    int row;
    int col;
    int free;
    int i;

    for (row = 1; row < 15; row++) {
        for (col = 1; col < 15; col++) {
            if (last_part != -1) {

                // Any cell that holds a part of a kind in the range will do.
                if (this->cells[col + row * chronicle::dungeon::GridStride].parts_no >= first_part && this->cells[col + row * chronicle::dungeon::GridStride].parts_no <= last_part) {
                    list[num * 2] = col;
                    list[num * 2 + 1] = row;
                    num++;

                    if (num >= max - 1) {
                        row = 16;
                        break;
                    }
                }
            } else {
                free = 1;

                // A cell that touches one that is already spoken for will not.
                for (i = 0; i < 4; i++) {
                    int dx = adjacent.offset[i][0];
                    int dy = adjacent.offset[i][1];
                    int cell_no = dx + (col + (row + dy) * chronicle::dungeon::GridStride);

                    if (this->cells[cell_no].parts_no != MAP_PARTS_NONE && (buildMapDat[cell_no].content & BUILD_CELL_ROOM_LINK) == BUILD_CELL_ROOM_LINK) {
                        free = 0;
                    }
                }

                if (this->cells[col + row * chronicle::dungeon::GridStride].parts_no == first_part && free != 0) {
                    list[num * 2] = col;
                    list[num * 2 + 1] = row;
                    num++;

                    if (num >= max - 1) {
                        row = 16;
                        break;
                    }
                }
            }
        }
    }

    return num;
}

